import './BookCard.css';
import type { Book, BookStatus } from '../../types';

const STATUS_LABELS: Record<BookStatus, string> = {
  'to-read': 'To Read',
  reading: 'Reading',
  read: 'Read',
};

const STATUS_CLASS: Record<BookStatus, string> = {
  'to-read': 'book-card-badge-to-read',
  reading: 'book-card-badge-reading',
  read: 'book-card-badge-read',
};

interface BookCardProps {
  book: Book;
}

export function BookCard({ book }: BookCardProps): JSX.Element {
  const { title, author, status } = book;

  return (
    <article className="book-card">
      <h2 className="book-card-title">{title}</h2>
      <p className="book-card-author">{author}</p>
      <span className={`book-card-badge ${STATUS_CLASS[status]}`}>
        {STATUS_LABELS[status]}
      </span>
    </article>
  );
}
